// Validation-only case appended to the existing Host-face test file; product source stays pinned.
it('DSH-Next right-click reuses session actions without opening the target', async () => {
  const scaffold = await launchWebScaffold({ extraInstallAnchors: [join(FIXTURE, 'package.json')] })
  onTestFinished(() => scaffold.close())
  const workspace = await scaffold.ctx.workspaceRegistry.create(scaffold.workspaceCwd)
  const seed = await readFile(SESSION_SEED, 'utf8')
  const currentId = await seedSession(scaffold, seed, 'session-c4421b66-252e-44c0-80ed-6e320abeba21')
  const targetId = await seedSession(scaffold, seed, 'session-c4421b66-252e-44c0-80ed-6e320abeba22')
  await workspace.attachSession(currentId)
  await workspace.attachSession(targetId)
  await scaffold.ctx.sessionController.rename({ sessionId: currentId, title: 'Next current session' })
  await scaffold.ctx.sessionController.rename({ sessionId: targetId, title: 'Next context target' })
  await scaffold.ctx.loader.create({ name: '@fixture/live-client' })
  const browser = await chromium.launch()
  try {
    const page = await newEnglishPage(browser)
    const observed = watchConsole(page)
    onTestFailed(() => saveFailureShot(page, 'dsh-next-context-menu'))
    await page.goto(scaffold.authenticatedUrl, { waitUntil: 'load' })
    const current = page.getByRole('treeitem').filter({ has: page.getByText('Next current session', { exact: true }) })
    const target = page.getByRole('treeitem').filter({ has: page.getByText('Next context target', { exact: true }) })
    await current.waitFor({ timeout: 20_000 })
    await target.waitFor({ timeout: 20_000 })
    await current.click()
    await expect.poll(() => current.getAttribute('aria-selected')).toBe('true')
    await expect.poll(() => target.getAttribute('aria-selected')).toBe('false')
    const selectedUrl = page.url()
    const trigger = target.getByRole('button', { name: 'Session actions for Next context target' })
    const menu = page.getByRole('menu')
    const names = () => menu.getByRole('menuitem').allTextContents()
    await target.hover()
    await trigger.click()
    await menu.waitFor()
    const regularActions = await names()
    expect(regularActions.length).toBeGreaterThan(0)
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    await target.getByText('Next context target', { exact: true }).click({ button: 'right' })
    await menu.waitFor()
    expect(await names()).toEqual(regularActions)
    expect(await current.getAttribute('aria-selected')).toBe('true')
    expect(await target.getAttribute('aria-selected')).toBe('false')
    expect(page.url()).toBe(selectedUrl)
    await menu.getByRole('menuitem', { name: 'Export session', exact: true }).click()
    await expect.poll(() => menu.count()).toBe(0)
    expect(await page.evaluate(() => ({
      action: document.documentElement.dataset.sessionAction,
      id: document.documentElement.dataset.sessionActionId,
      title: document.documentElement.dataset.sessionActionTitle,
    }))).toEqual({ action: 'fixture.export-session', id: targetId, title: 'Next context target' })
    expect(await current.getAttribute('aria-selected')).toBe('true')
    expect(page.url()).toBe(selectedUrl)
    await target.click({ button: 'right' })
    await menu.waitFor()
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    await target.click({ button: 'right' })
    await menu.waitFor()
    await page.mouse.click(1, 1)
    await expect.poll(() => menu.count()).toBe(0)
    await scaffold.ctx.workspaceRegistry.archiveSession(targetId)
    await expect.poll(() => target.count()).toBe(0)
    await page.getByRole('button', { name: 'View options', exact: true }).click()
    await page.getByRole('menuitem', { name: 'All conversations (show archived)', exact: true }).click()
    await target.waitFor()
    await target.hover()
    await trigger.click()
    await menu.waitFor()
    const archivedActions = await names()
    expect(archivedActions.length).toBeGreaterThan(0)
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    await target.click({ button: 'right' })
    await menu.waitFor()
    expect(await names()).toEqual(archivedActions)
    expect(await current.getAttribute('aria-selected')).toBe('true')
    expect(await target.getAttribute('aria-selected')).toBe('false')
    expect(page.url()).toBe(selectedUrl)
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    expect(observed.pageErrors).toEqual([])
  } finally {
    await browser.close()
  }
})

import { vi as workspaceMenuVi } from 'vitest'

// Only the OS effect and capability are mocked; the real browser, Remote and Host path verification remain composed.
it('DSH-Next workspace menu opens only the clicked Host folder', async () => {
  const scaffold = await launchWebScaffold()
  const controller = scaffold.ctx.sessionController
  const originalOpen = Object.getOwnPropertyDescriptor(controller, 'openPath')
  const originalCanOpen = Object.getOwnPropertyDescriptor(controller, 'canOpenPath')
  // Source imports and built Loader modules need not share identity: intercept the actual serving instance.
  onTestFinished(async () => {
    try { await scaffold.close() }
    finally {
      if (originalOpen) Object.defineProperty(controller, 'openPath', originalOpen)
      if (originalCanOpen) Object.defineProperty(controller, 'canOpenPath', originalCanOpen)
    }
  })
  expect(originalOpen?.writable).toBe(true)
  expect(originalCanOpen?.writable).toBe(true)
  expect(typeof originalOpen?.value).toBe('function')
  expect(typeof originalCanOpen?.value).toBe('function')
  const opened = workspaceMenuVi.fn(async (_path: string, signal: AbortSignal) => { signal.throwIfAborted() })
  expect(Reflect.set(controller, 'openPath', opened)).toBe(true)
  expect(Reflect.set(controller, 'canOpenPath', () => true)).toBe(true)
  // Cordis wraps service methods on access; verify the backing slot before safely probing the wrapper.
  expect(Object.getOwnPropertyDescriptor(controller, 'openPath')?.value).toBe(opened)
  const probePath = '/synthetic-next-workspace-opener-probe'
  const probeSignal = new AbortController().signal
  await Reflect.get(controller, 'openPath')(probePath, probeSignal)
  expect(opened).toHaveBeenCalledExactlyOnceWith(probePath, probeSignal)
  opened.mockClear()
  const currentWorkspace = await scaffold.ctx.workspaceRegistry.create(scaffold.workspaceCwd)
  await currentWorkspace.setTitle('Next current workspace')
  const targetPath = await mkdtemp(join(scaffold.workspaceCwd, 'Next 中文 folder,= & '))
  const targetWorkspace = await scaffold.ctx.workspaceRegistry.create(targetPath)
  await targetWorkspace.setTitle('Next folder target')
  const currentId = await seedSession(scaffold, await readFile(SESSION_SEED, 'utf8'), 'session-c4421b66-252e-44c0-80ed-6e320abeba23')
  await currentWorkspace.attachSession(currentId)
  await scaffold.ctx.sessionController.rename({ sessionId: currentId, title: 'Next folder current session' })
  const browser = await chromium.launch()
  try {
    const page = await newEnglishPage(browser)
    const observed = watchConsole(page)
    onTestFailed(() => saveFailureShot(page, 'dsh-next-workspace-menu'))
    await page.goto(scaffold.authenticatedUrl, { waitUntil: 'load' })
    const currentGroup = page.locator(`[data-row-key="workspace:${currentWorkspace.id}"]`)
    await currentGroup.waitFor({ timeout: 20_000 })
    if (await currentGroup.getAttribute('aria-expanded') === 'false') await currentGroup.click()
    const current = page.locator(`[data-row-key="session:${currentId}"]`)
    const target = page.locator(`[data-row-key="workspace:${targetWorkspace.id}"]`)
    await current.waitFor({ timeout: 20_000 })
    await target.waitFor({ timeout: 20_000 })
    await current.click()
    await expect.poll(() => current.getAttribute('aria-selected')).toBe('true')
    const selectedUrl = page.url()
    const expanded = await target.getAttribute('aria-expanded')
    const menu = page.getByRole('menu')
    const title = target.getByText('Next folder target', { exact: true })
    const assertUnchanged = async () => {
      expect(await current.getAttribute('aria-selected')).toBe('true')
      expect(await target.getAttribute('aria-expanded')).toBe(expanded)
      expect(page.url()).toBe(selectedUrl)
    }
    await title.click({ button: 'right' })
    await menu.waitFor()
    await title.click({ button: 'right' })
    expect(await menu.count()).toBe(1)
    expect(opened).not.toHaveBeenCalled()
    await assertUnchanged()
    expect(await menu.getByRole('menuitem', { name: 'Rename', exact: true }).count()).toBe(1)
    expect(await menu.getByRole('menuitem', { name: 'Delete workspace', exact: true }).count()).toBe(1)
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    await target.focus()
    await page.keyboard.press('Shift+F10')
    await menu.waitFor()
    expect(opened).not.toHaveBeenCalled()
    await page.keyboard.press('Escape')
    await expect.poll(() => menu.count()).toBe(0)
    await target.focus()
    await page.keyboard.press('ContextMenu')
    await menu.waitFor()
    await page.mouse.click(1, 1)
    await expect.poll(() => menu.count()).toBe(0)
    expect(opened).not.toHaveBeenCalled()
    await assertUnchanged()
    await title.click({ button: 'right' })
    await menu.getByRole('menuitem', { name: 'Open workspace folder', exact: true }).click()
    await expect.poll(() => opened.mock.calls.length).toBe(1)
    expect(opened.mock.calls[0]?.[0]).toBe(targetWorkspace.path)
    expect(opened.mock.calls[0]?.[0]).not.toBe(currentWorkspace.path)
    await expect.poll(() => menu.count()).toBe(0)
    await assertUnchanged()
    await target.focus()
    await page.keyboard.press('Shift+F10')
    await menu.getByRole('menuitem', { name: 'Open workspace folder', exact: true }).focus()
    await page.keyboard.press('Enter')
    await expect.poll(() => opened.mock.calls.length).toBe(2)
    expect(opened.mock.calls[1]?.[0]).toBe(targetWorkspace.path)
    await expect.poll(() => menu.count()).toBe(0)
    await assertUnchanged()
    expect(observed.pageErrors).toEqual([])
  } finally { await browser.close() }
}, 120_000)
